+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** Theoretical vs actual ingredient use per item between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const theoreticalByItem = new Map();
+  for (const sale of store.data.sales ?? []) {
+    const day = dayOf(sale.soldAt);
+    if (day < from || day > to) continue;
+    const dish = getDish(store, sale.dishId);
+    const recipe = getRecipe(store, dish.recipeId);
+    for (const n of scaled(recipe, sale.qty)) {
+      theoreticalByItem.set(n.itemId, (theoreticalByItem.get(n.itemId) ?? 0) + n.qty);
+    }
+  }
+
+  const actualByItem = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actualByItem.set(batch.itemId, (actualByItem.get(batch.itemId) ?? 0) + m.qty);
+  }
+
+  const ids = new Set([...theoreticalByItem.keys(), ...actualByItem.keys()]);
+  const lines = [];
+  for (const itemId of ids) {
+    const theoretical = round3(theoreticalByItem.get(itemId) ?? 0);
+    const actual = round3(actualByItem.get(itemId) ?? 0);
+    if (theoretical > 0 || actual > 0) {
+      lines.push({
+        itemId,
+        name: getItem(store, itemId).name,
+        theoretical,
+        actual,
+        variance: round3(actual - theoretical),
+      });
+    }
+  }
+  return lines.sort((a, b) => a.itemId - b.itemId);
+}
