diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..23a0836
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,81 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Each dish sold consumes one portion of its recipe per qty, with ledger ref
+// "sale:<ticket>". Tickets already imported are skipped. The whole file is
+// checked first; one bad row or missing stock and nothing is imported.
+import { AppError } from "../errors.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports till sales; returns { tickets, dishes } counts or throws bad_request naming the row. */
+export function importSales(store, text) {
+  const rows = parseCsvObjects(text);
+  const existingTickets = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const remaining = new Map();
+
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    for (const k of HEADER) {
+      if (!(k in r)) throw new AppError("bad_request", { reason: `${where}: missing column ${k}` });
+    }
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!/^\d{4}-\d{2}-\d{2}T/.test(r.soldAt) || !Number.isFinite(Date.parse(r.soldAt))) {
+      throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    }
+    const soldAt = new Date(r.soldAt).toISOString();
+    const dishId = Number(r.dishId);
+    if (!Number.isInteger(dishId) || dishId < 1) {
+      throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    }
+    const dish = (store.data.dishes ?? []).find((d) => d.id === dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish ${dishId}` });
+    const qty = Number(r.qty);
+    if (!Number.isFinite(qty) || !(qty > 0) || Math.round(qty * 1000) !== qty * 1000) {
+      throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    }
+
+    if (existingTickets.has(r.ticket)) {
+      return { skip: true, ticket: r.ticket, soldAt, dishId, qty, needs: [] };
+    }
+
+    const recipe = getRecipe(store, dish.recipeId);
+    const needs = scaled(recipe, qty);
+    for (const n of needs) {
+      const item = getItem(store, n.itemId);
+      const avail = remaining.get(n.itemId) ?? onHand(store, n.itemId);
+      if (avail < n.qty) {
+        throw new AppError("bad_request", {
+          reason: `${where}: not enough ${item.name} (only ${avail} ${item.unit} left)`,
+        });
+      }
+      remaining.set(n.itemId, Math.round((avail - n.qty) * 1000) / 1000);
+    }
+
+    return { skip: false, ticket: r.ticket, soldAt, dishId, qty, needs };
+  });
+
+  store.data.sales ??= [];
+  const importedTickets = new Set();
+  let dishes = 0;
+
+  for (const c of clean) {
+    if (c.skip) continue;
+    for (const n of c.needs) {
+      if (n.qty > 0) consume(store, n.itemId, n.qty, { at: c.soldAt, ref: `sale:${c.ticket}` });
+    }
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: c.ticket,
+      soldAt: c.soldAt,
+      dishId: c.dishId,
+      qty: c.qty,
+    });
+    importedTickets.add(c.ticket);
+    dishes = Math.round((dishes + c.qty) * 1000) / 1000;
+  }
+
+  return { tickets: importedTickets.size, dishes };
+}
